    #[doc = r" `100000012345678@lid`) or `null` when no mapping is known. Backed by"]
    #[doc = r" the core's cache-aside `get_lid_pn_entry`: hits the in-memory cache"]
    #[doc = r" first, then falls through to `backend.get_pn_mapping(user)` so a JS"]
    #[doc = r" `JsStoreCallbacks` backend without a list primitive still resolves"]
